export const DIRECT_TYPES_DEFAULT = ['Bug', 'Outage', 'Performance', 'Access issue'];
const KW = (s) => (s || '').toLowerCase().split(/[^a-z0-9]+/).filter(w => w.length > 3 && !['fails', 'after', 'when', 'with', 'from', 'that', 'this', 'does', 'cannot', 'issue'].includes(w));
const note = (text, tone) => ({ text, style: tone === 'warn' ? 'background:#fbf6ea;border:1px solid #f0d9b0;border-radius:8px;padding:9px 12px;color:#7a5410;font-size:12px' : tone === 'danger' ? 'background:#fbe9e3;border:1px solid #f0c9bd;border-radius:8px;padding:9px 12px;color:#a8321f;font-size:12px' : tone === 'good' ? 'background:#f6faf7;border:1px solid #cfe0d3;border-radius:8px;padding:9px 12px;color:#1f5a33;font-size:12px' : 'background:#fafaf8;border:1px solid #e4e4e0;border-radius:8px;padding:9px 12px;color:#4a4b4e;font-size:12px' });

