// ---------- engine ----------
export function owner(A, projectId) { return A.D.ownership[projectId] || A.D.ownership.p_crm; }
export function available(A, uid, projectId) { const av = A.D.availability[uid]; if (av) return { ok: false, why: `${A.name(uid)} is ${av.status.toLowerCase()} until ${av.until}` }; const o = owner(A, projectId); const load = A.D.tickets.filter(t => t.assignedTo === uid && !['RESOLVED', 'CLOSED', 'CANCELLED'].includes(t.status)).length + A.D.tasks.filter(t => t.assignedTo === uid && ['IN_PROGRESS', 'ASSIGNED'].includes(t.status)).length; if (load >= o.limit) return { ok: false, why: `${A.name(uid)} is at workload limit (${load}/${o.limit})` }; return { ok: true }; }
export function route(A, tk) {
  const o = owner(A, tk.projectId); const R = A.D.routing; const direct = R.directTypes.includes(tk.type); const trail = [];
  if (!direct) { tk.status = 'NEW'; tk.team = 'Support'; tk.assignedTo = null; tk.routedNote = `${tk.type} → support team queue`; return; }
  const cands = [[o.modules[tk.module], `Module owner · ${tk.module}`], [o.primary, 'Primary support developer'], [today(A, tk.projectId), 'On-call today'], [o.backup, 'Backup developer']].filter(c => c[0] && c[0] !== '—');
  for (const [uid, why] of cands) { const av = available(A, uid, tk.projectId); if (av.ok) { tk.assignedTo = uid; tk.team = 'Alpha'; tk.status = 'AUTO_ASSIGNED'; tk.ackDue = A.D.clock + R.ackMinutes; tk.escalationLevel = 0; tk.assignments.push({ kind: 'AUTO', to: uid, at: '04/09 ' + A.now(), reason: (trail.length ? trail.join('; ') + ' → ' : '') + why }); tk.routedNote = why; A.notify(uid, `New ${tk.type.toLowerCase()} ticket ${tk.id} auto-assigned — acknowledge within ${R.ackMinutes} min`, 'ticketDetail', tk.id); A.notify(o.senior, `${tk.id} routed to ${A.name(uid)} (${why})`, 'ticketDetail', tk.id); A.audit('ROUTING', `${tk.id} auto-assigned to ${A.name(uid)} — ${why}`); return; } trail.push(`${A.name(uid)} skipped: ${av.why}`); }
  tk.status = 'ESCALATED'; tk.assignedTo = o.senior; tk.escalationLevel = 2; tk.assignments.push({ kind: 'ESCALATE_L2', to: o.senior, at: '04/09 ' + A.now(), reason: 'No developer available: ' + trail.join('; ') }); tk.routedNote = 'No developer available — escalated to senior'; A.notify(o.senior, `${tk.id}: no developer available — escalated to you`, 'ticketDetail', tk.id);
}
export function today(A, projectId) { const d = A.D.oncall[0]; return d ? d[projectId] : null; }
export function afterRaise(A, tk) { const cb = A.D.callbacks.find(c => c.ticketId === tk.id && !c.assignedTo); tk.module = tk.module || 'General'; tk.version = tk.version || (A.P(tk.projectId) ? A.P(tk.projectId).envs.prodVersion : ''); tk.assignments = []; tk.calls = []; tk.escalationLevel = 0; tk.nextUpdate = `in ${A.D.routing.nextUpdateHours}h`; route(A, tk); if (cb) { cb.assignedTo = tk.assignedTo || owner(A, tk.projectId).support; A.notify(cb.assignedTo, `${tk.id}: client asked for a call (${cb.due})`, 'ticketDetail', tk.id); } const sim = similar(A, tk); if (sim.length) { tk.similarCount = sim.length; A.notify(owner(A, tk.projectId).senior, `${tk.id} looks similar to ${sim.length} other ticket(s) — review for a Problem`, 'ticketDetail', tk.id); } checkThreshold(A, tk, sim); }
export function similar(A, tk) { const kw = new Set(KW(tk.title + ' ' + tk.desc)); return A.D.tickets.filter(x => x.id !== tk.id && x.projectId === tk.projectId && !['CANCELLED'].includes(x.status)).map(x => { let score = 0; const sig = []; if (x.module === tk.module) { score += 2; sig.push('module'); } if (x.version === tk.version) { score += 1; sig.push('version'); } const ov = KW(x.title + ' ' + x.desc).filter(w => kw.has(w)); if (ov.length) { score += ov.length; sig.push('keywords: ' + ov.slice(0, 3).join(', ')); } if (x.type === tk.type) score += .5; return { t: x, score, sig }; }).filter(m => m.score >= 3).sort((a, b) => b.score - a.score); }
export function checkThreshold(A, tk, sim) { const R = A.D.routing; const grp = [tk].concat(sim.map(m => m.t)); const orgs = new Set(grp.map(x => x.orgId)); const existing = grp.map(x => x.problemId).find(Boolean); if (existing) return; if (orgs.size >= R.threshold) { const p = createProblem(A, grp, 'system'); A.notify(owner(A, tk.projectId).senior, `Problem ${p.id} auto-created: ${orgs.size} clients report "${tk.title}"`, 'problemDetail', p.id); } }
export function createProblem(A, tickets, by) { const t0 = tickets[0]; const p = { id: 'PRB-' + (A.D.counter.problem++), title: t0.title, projectId: t0.projectId, module: t0.module, versions: [...new Set(tickets.map(x => x.version))], severity: tickets.some(x => x.priority === 'Critical') ? 'Critical' : 'High', status: 'OPEN', ownerId: owner(A, t0.projectId).modules[t0.module] || owner(A, t0.projectId).primary, ticketIds: tickets.map(x => x.id), fixTaskId: null, createdAt: '04/09 ' + A.now(), rca: null, questions: [], preventiveTest: null, timeline: [{ at: '04/09 ' + A.now(), text: by === 'system' ? `Auto-created — ${new Set(tickets.map(x => x.orgId)).size} clients crossed the threshold of ${A.D.routing.threshold}` : `Created by ${A.name(by)} from ${tickets.length} ticket(s)` }] }; tickets.forEach(x => x.problemId = p.id); A.D.problems.unshift(p); A.audit('PROBLEM', `${p.id} created (${p.ticketIds.join(', ')})`); return p; }
export function escalateOverdue(A) { const R = A.D.routing; let n = 0; A.D.tickets.forEach(tk => { if (!['AUTO_ASSIGNED', 'ESCALATED'].includes(tk.status) || tk.ackDue == null || A.D.clock < tk.ackDue) return; const o = owner(A, tk.projectId); if (tk.escalationLevel === 0) { const to = o.backup !== tk.assignedTo && available(A, o.backup, tk.projectId).ok ? o.backup : today(A, tk.projectId) !== tk.assignedTo ? today(A, tk.projectId) : o.senior; tk.escalationLevel = 1; tk.status = 'ESCALATED'; tk.assignments.push({ kind: 'ESCALATE_L1', from: tk.assignedTo, to, at: '04/09 ' + A.now(), reason: `No acknowledgement within ${R.ackMinutes} min` }); tk.assignedTo = to; tk.ackDue = A.D.clock + R.escalationMinutes - R.ackMinutes; A.notify(to, `${tk.id} escalated to you — ${A.name(tk.assignments[tk.assignments.length - 1].from)} did not acknowledge`, 'ticketDetail', tk.id); A.notify(o.senior, `${tk.id} escalated L1 → ${A.name(to)}`, 'ticketDetail', tk.id); A.audit('ESCALATION', `${tk.id} L1 → ${A.name(to)}`); n++; } else if (tk.escalationLevel === 1) { tk.escalationLevel = 2; tk.assignments.push({ kind: 'ESCALATE_L2', from: tk.assignedTo, to: o.senior, at: '04/09 ' + A.now(), reason: 'Backup did not acknowledge' }); tk.assignedTo = o.senior; tk.ackDue = null; tk.slaBreach = true; A.notify(o.senior, `${tk.id} escalated L2 to you — SLA at risk`, 'ticketDetail', tk.id); A.audit('ESCALATION', `${tk.id} L2 → ${A.name(o.senior)}`); n++; } }); return n; }
export function ackState(A, tk) { if (!['AUTO_ASSIGNED', 'ESCALATED'].includes(tk.status) || tk.ackDue == null) return null; const left = tk.ackDue - A.D.clock; return left >= 0 ? { text: `ack due in ${left} min`, red: left < 5 } : { text: `ack overdue by ${-left} min`, red: true }; }
export function canSupport(A, tk, action) { const rk = A.S.roleKey, me = A.me.id, mine = tk.assignedTo === me; const no = (r) => ({ ok: false, reason: r }); const ok = { ok: true, reason: '' }; const closed = ['RESOLVED', 'CLOSED', 'CANCELLED'].includes(tk.status); const inHours = A.D.clock >= 8 * 60 && A.D.clock <= 22 * 60;
  switch (action) {
    case 'accept': if (!['AUTO_ASSIGNED', 'ESCALATED'].includes(tk.status)) return no(tk.status === 'ACKNOWLEDGED' ? 'Already acknowledged' : `Not awaiting acknowledgement (${TICKET_STATUS[tk.status].label})`); return mine || A.isMgr ? ok : no(`Only ${A.name(tk.assignedTo)} (assignee) can accept`);
    case 'startWork': if (tk.status !== 'ACKNOWLEDGED') return no(tk.status === 'AUTO_ASSIGNED' || tk.status === 'ESCALATED' ? 'Accept the ticket first' : `Not in Acknowledged (${TICKET_STATUS[tk.status].label})`); return mine || A.isMgr ? ok : no('Only the assignee');
    case 'escalate': if (closed) return no('Ticket is closed'); if (A.isClient) return no('Internal action'); if (tk.escalationLevel >= 2) return no('Already with the senior'); return (mine || A.isMgr || rk === 'support') ? ok : no('Only the assignee, Support or a manager');
    case 'reassign': if (closed) return no('Ticket is closed'); return (A.isMgr || rk === 'support') ? ok : no('Only Support, PM, Lead or Admin — reason required');
    case 'call': if (A.S.offline) return no('Offline — calls are bridged by the backend IVR; reconnect to call or request a callback'); if (A.isClient) return no('Clients call the support number; developers are never dialled directly'); if (closed) return no('Ticket is closed'); if (!inHours) return no('Outside working hours — request a callback instead'); if (A.D.availability[me]) return no('You are marked on leave'); return (mine || A.isMgr || rk === 'support') ? ok : no('Only the assignee, Support or a manager');
    case 'linkDup': case 'createProblem': if (A.isClient) return no('Internal'); return (A.isMgr || rk === 'support') ? ok : no('Developers can suggest; Support/PM/Lead confirm');
    case 'requestRca': case 'closeProblem': case 'assignFix': return A.isMgr ? ok : no('Only PM, Lead or Admin');
    case 'submitRca': return ok;
    case 'preventiveTest': return (A.isMgr || A.isTester) ? ok : no('QA or a manager adds preventive tests');
  } return no(''); }

// ---------- modals ----------
export function acceptTicket(A, tkId) { const tk = A.TK(tkId); tk.status = 'ACKNOWLEDGED'; tk.acknowledgedAt = '04/09 ' + A.now(); tk.ackDue = null; tk.firstResponse = tk.firstResponse || A.now(); tk.assignments.push({ kind: 'ACK', to: A.me.id, at: tk.acknowledgedAt, reason: 'Accepted' }); A.audit('TICKET', `${tk.id} acknowledged by ${A.me.name}`); A.notify(tk.requesterId, `Your ticket ${tk.id} is being looked at by our team. Next update ${tk.nextUpdate}.`, 'portalTicketDetail', tk.id); A.save(); A.toast('Accepted — SLA clock continues, client informed'); }
export function startTicketWork(A, tkId) { const tk = A.TK(tkId); const p = A.P(tk.projectId); A.modal({ title: 'Start work', subtitle: `${tk.id} · creates the linked development task`, width: 520, fields: [{ key: 'title', type: 'text', label: 'Task title', full: true, value: tk.title }, { key: 'priority', type: 'select', label: 'Priority', options: ['Low', 'Medium', 'High', 'Critical'].map(v => ({ value: v, label: v })), value: tk.priority }, { key: 'vis', type: 'toggle', label: 'Client-visible', toggleLabel: 'Completion posts as a public reply', value: true }], notes: [note('The ticket follows the task: code review → staging → QA → (UAT) → release → live smoke test → Resolved. You cannot close it by hand after coding.')], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Start work', kind: 'primary', onClick: () => { const id = 'AD-' + (A.D.counter.task++); A.D.tasks.unshift({ id, projectId: p.id, title: A.val('title'), desc: tk.desc, category: 'Development', kind: 'DEV', status: 'IN_PROGRESS', priority: A.val('priority'), assignedBy: A.me.id, assignedTo: A.me.id, reviewerId: p.reviewerId, testerId: p.testerId, due: '05/09/2026', est: 3, actual: 0, clientVisible: !!A.val('vis'), clientUpdate: '', ticketId: tk.id, releaseId: null, pr: null, checks: null, staging: false, acceptance: [], comments: [], history: [{ from: 'ASSIGNED', to: 'IN_PROGRESS', by: A.me.id, at: '04/09 ' + A.now(), note: 'From ticket ' + tk.id }] }); tk.taskIds.push(id); tk.status = 'IN_PROGRESS'; A.audit('TICKET', `${tk.id} work started → ${id}`); A.save(); A.closeModal(); A.toast(`Working — task ${id} linked`); A.go('taskDetail', id); } }] }); }
export function escalateTicket(A, tkId) { const tk = A.TK(tkId); const o = owner(A, tk.projectId); A.modal({ title: 'Escalate ticket', subtitle: `${tk.id} · level ${tk.escalationLevel} → ${tk.escalationLevel + 1}`, width: 480, fields: [{ key: 'to', type: 'select', label: 'Escalate to', full: true, options: [[o.backup, 'Backup developer'], [o.senior, 'Responsible senior'], ['u_anita', 'Project manager']].map(([v, l]) => ({ value: v, label: `${A.name(v)} · ${l}` })), value: tk.escalationLevel === 0 ? o.backup : o.senior }, { key: 'urgent', type: 'toggle', label: 'Incident', toggleLabel: 'Urgent incident (outage / data risk)', value: tk.priority === 'Critical' }, { key: 'reason', type: 'area', label: 'Reason (required)', full: true }], actions: [{ label: 'Cancel', kind: 'secondary', onClick: () => A.closeModal() }, { label: 'Escalate', kind: 'danger', onClick: () => { const r = (A.val('reason') || '').trim(); if (!r) return A.toast('A reason is required'); const to = A.val('to'); tk.assignments.push({ kind: 'ESCALATE_L' + (tk.escalationLevel + 1), from: tk.assignedTo, to, at: '04/09 ' + A.now(), reason: r }); tk.assignedTo = to; tk.escalationLevel++; tk.status = 'ESCALATED'; tk.ackDue = A.D.clock + A.D.routing.ackMinutes; if (A.val('urgent')) { tk.incident = true; tk.priority = 'Critical'; } A.audit('ESCALATION', `${tk.id} escalated to ${A.name(to)} — ${r}`); A.notify(to, `${tk.id} escalated to you: ${r}`, 'ticketDetail', tk.id); A.save(); A.closeModal(); A.toast(`Escalated to ${A.name(to)}`); } }] }); }
