export function callClient(A, tkId) { const tk = A.TK(tkId); const o = A.O(tk.orgId); A.modal({ title: 'Call client through IVR', subtitle: `${tk.id} · ${tk.requesterName || A.name(tk.requesterId)} · ${o.name}`, width: 480, notes: [note('The IVR bridges both parties; neither personal number is shown. Recording starts only after the consent prompt.')], fields: [{ key: 'consent', type: 'toggle', label: 'Recording', toggleLabel: 'Play consent prompt and record', value: true }, { key: 'purpose', type: 'text', label: 'Purpose (internal)', full: true, value: 'Confirm affected devices' }], actions: [{ label: 'Request callback instead', kind: 'secondary', onClick: () => { A.D.callbacks.unshift({ id: 'CB-' + (A.D.counter.callback++), ticketId: tk.id, orgId: tk.orgId, requestedAt: '04/09 ' + A.now(), due: 'today ' + fmt(A.D.clock + 120), assignedTo: A.me.id, status: 'Scheduled' }); A.save(); A.closeModal(); A.toast('Callback scheduled in 2h'); } }, { label: 'Connect call', kind: 'good', onClick: () => { const c = { id: 'CALL-' + (A.D.counter.call++), ticketId: tk.id, orgId: tk.orgId, callerRef: `${tk.requesterName || A.name(tk.requesterId)} · +91 ••••• •7841`, agent: A.me.id, direction: 'Outbound', at: '04/09 ' + A.now(), duration: '', outcome: 'In progress', recording: A.val('consent') ? 'rec_pending' : null, consent: !!A.val('consent'), publicSummary: '', internalNote: '', nextAction: '' }; A.D.calls.unshift(c); tk.calls.push(c.id); A.audit('IVR', `${c.id} outbound via Tata IVR · ${tk.id}`); A.save(); inCall(A, c.id); } }] }); }
export function inCall(A, cid) { const c = A.D.calls.find(x => x.id === cid); const tk = A.TK(c.ticketId); A.modal({ title: `● On call · ${c.callerRef}`, subtitle: `${tk.id} · ${tk.title} · via Tata IVR · ${c.consent ? 'recording' : 'not recorded'}`, width: 520, lines: [{ text: `Client: ${A.O(tk.orgId).name} · Product: ${A.P(tk.projectId).name} ${tk.version} · Module: ${tk.module}`, style: 'font-size:12.5px;color:#4a4b4e' }, { text: `Previous: ${tk.replies.length} messages · ${tk.calls.length - 1} earlier call(s) · linked tasks ${tk.taskIds.join(', ') || 'none'}`, style: 'font-size:12.5px;color:#4a4b4e' }], fields: [{ key: 'notes', type: 'area', label: 'Live notes (internal)', full: true }], actions: [{ label: 'Transfer to backup', kind: 'secondary', onClick: () => { c.outcome = 'Transferred'; c.duration = '1m 05s'; c.internalNote = A.val('notes') || ''; const o = owner(A, tk.projectId); A.notify(o.backup, `Call on ${tk.id} transferred to you`, 'ticketDetail', tk.id); A.save(); A.closeModal(); A.toast(`Transferred to ${A.name(o.backup)}`); } }, { label: 'End call', kind: 'danger', onClick: () => { c.duration = `${3 + Math.floor(Math.random() * 6)}m ${10 + Math.floor(Math.random() * 40)}s`; c.outcome = 'Connected'; if (c.recording) c.recording = 'rec_' + c.id.toLowerCase(); c.internalNote = A.val('notes') || ''; A.save(); disposition(A, cid); } }] }); }
export function disposition(A, cid) { const c = A.D.calls.find(x => x.id === cid); const tk = A.TK(c.ticketId); A.modal({ title: 'Call wrap-up', subtitle: `${c.id} · ${c.duration} · ${c.outcome}`, width: 520, fields: [{ key: 'disp', type: 'seg', label: 'Disposition', options: ['Resolved on call', 'Info gathered', 'Needs fix', 'Callback needed'].map(v => ({ value: v, label: v })), value: 'Info gathered' }, { key: 'pub', type: 'text', label: 'Public summary (client sees)', full: true, value: 'We discussed the issue and confirmed the next steps.' }, { key: 'int', type: 'area', label: 'Internal note', full: true, value: c.internalNote }, { key: 'next', type: 'select', label: 'Next action', options: ['Start work', 'Send for review', 'Wait for client', 'Schedule callback', 'Escalate', 'None'].map(v => ({ value: v, label: v })), value: 'Start work' }], footer: 'Only these four fields — the call time, duration and recording reference attach automatically.', actions: [{ label: 'Save', kind: 'primary', onClick: () => { c.disposition = A.val('disp'); c.publicSummary = A.val('pub'); c.internalNote = A.val('int'); c.nextAction = A.val('next'); tk.replies.push({ by: A.me.id, at: '04/09 ' + A.now(), body: `📞 Call (${c.duration}): ${c.publicSummary}`, pub: true }); if (c.nextAction === 'Schedule callback') A.D.callbacks.unshift({ id: 'CB-' + (A.D.counter.callback++), ticketId: tk.id, orgId: tk.orgId, requestedAt: '04/09 ' + A.now(), due: 'tomorrow 10:00', assignedTo: A.me.id, status: 'Scheduled' }); if (c.nextAction === 'Wait for client') tk.status = 'WAITING_CLIENT'; A.audit('IVR', `${c.id} wrap-up · ${c.disposition}`); A.save(); A.closeModal(); A.toast('Call logged on the ticket'); } }] }); }
